import os, uuid
from datetime import datetime
from pyspark.sql import functions as F, types as T
from pyspark.sql.window import Window
from notebookutils import mssparkutils

if STORAGE_KEY:
    spark.conf.set("fs.azure.account.key.pinssts62adevukseftlkl.dfs.core.windows.net",
                   mssparkutils.credentials.getSecretWithLS(*STORAGE_KEY).strip())

RUN_TS = datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")

# Same GUID rule as the case notebooks -> uuid5(namespace, "S62aCase|<reference>"), uppercase
GUID_NS = uuid.uuid5(uuid.NAMESPACE_URL, "pins-s62a-migration")

@F.udf(T.StringType())
def make_guid(*parts):
    if any(p is None for p in parts):
        return None
    return str(uuid.uuid5(GUID_NS, "|".join(str(p) for p in parts))).upper()

# Write Folder.csv and Document.csv with fixed names (comma, double-quote escaping - same format as SCHEMA/latest)
tmp = "/tmp/s62a_documents"
os.makedirs(tmp, exist_ok=True)

outputs = {
    "Folder.csv": folders_final,
    "Document.csv": docs_with_mime.drop("pathSegments", "ancestorPaths"),
}
for name, frame in outputs.items():
    frame.toPandas().to_csv(f"{tmp}/{name}", index=False, encoding="utf-8")

for folder in (RUN_TS, "latest"):
    dest = f"{OUTPUT_DIR}/{folder}"
    if folder == "latest":
        try:
            mssparkutils.fs.rm(dest, True)
        except Exception:
            pass
    for name in outputs:
        mssparkutils.fs.cp(f"file:{tmp}/{name}", f"{dest}/{name}")
    print("Written to", dest)
